   229	        if stripped.startswith("- "):
   230	            flush_para()
   231	            if not in_list:
   232	                out.append("<ul>")
   233	                in_list = True
   234	            out.append(f"<li>{render_inline(stripped[2:].strip())}</li>")
   235	            continue
   236	
   237	        close_list()
   238	        para.append(stripped)
   239	
   240	    flush_para()
   241	    close_list()
   242	    return "\n".join(out)
