   245	def load_jobs(today: date) -> list[Job]:
   246	    jobs: list[Job] = []
   247	    for path in sorted(SOURCE_DIR.glob("*.md")):
   248	        if path.name in SKIP_FILES:
   249	            continue
   250	        raw = path.read_text(encoding="utf-8")
   251	        meta, body = parse_front_matter(raw, path)
   252	
   253	        missing = [field for field in REQUIRED_FIELDS if not clean_text(meta.get(field))]
   254	        if missing:
   255	            raise ValueError(f"{path}: thiếu field bắt buộc {missing}")
   256	
   257	        publish_date = parse_date(clean_text(meta["publishDate"]), "publishDate", path)
   258	        deadline = parse_date(clean_text(meta["deadline"]), "deadline", path)
   259	        href = f"tuyen-dung/{clean_text(meta['slug'])}.html"
   260	        detail_path = OUTPUT_DIR / f"{clean_text(meta['slug'])}.html"
   261	        effective_status = infer_effective_status(meta, deadline, today)
   262	
   263	        meta = dict(meta)
   264	        meta["status"] = effective_status
   265	        meta["publishDate"] = publish_date.isoformat()
   266	        meta["deadline"] = deadline.isoformat()
   267	        meta["href"] = href
   268	        meta["salaryLabel"] = clean_text(meta.get("salaryLabel"))
   269	        meta["location"] = clean_text(meta.get("location"))
   270	        meta["summary"] = clean_text(meta.get("summary"))
   271	        meta["companyName"] = clean_text(meta.get("companyName"))
   272	        meta["title"] = clean_text(meta.get("title"))
   273	        meta["workMode"] = clean_text(meta.get("workMode"))
   274	        meta["employmentType"] = clean_text(meta.get("employmentType"))
   275	        meta["experienceLevel"] = clean_text(meta.get("experienceLevel"))
   276	        meta["featured"] = bool(meta.get("featured"))
   277	        meta["urgent"] = bool(meta.get("urgent"))
   278	        meta["tags"] = meta.get("tags") or []
   279	        location_key, location_label = infer_location_group(meta["location"], meta["tags"])
   280	        meta["locationGroupKey"] = location_key
   281	        meta["locationGroupLabel"] = location_label
   282	        role_key, role_label = infer_role_group(meta["title"], meta["tags"])
   283	        meta["roleGroupKey"] = role_key
   284	        meta["roleGroupLabel"] = role_label
   285	
   286	        jobs.append(
   287	            Job(
   288	                meta=meta,
   289	                body_markdown=body,
   290	                body_html=markdown_to_html(body),
   291	                href=href,
   292	                detail_path=detail_path,
   293	                publish_date=publish_date,
   294	                deadline=deadline,
   295	                effective_status=effective_status,
   296	            )
   297	        )
