   460	        }
   461	
   462	        function applyFilters() {
   463	          var searchValue = normalizeText(searchInput ? searchInput.value : '');
   464	          var locationValue = locationSelect ? locationSelect.value : '';
   465	          var roleValue = roleSelect ? roleSelect.value : '';
